idosal/git-mcp.quickStart:
# 1. 选择服务器 URL 格式
gitmcp.io/{owner}/{repo}
{owner}.gitmcp.io/{repo}
gitmcp.io/docs
# 2. 在 ~/.cursor/mcp.json 中添加
{
  "mcpServers": {
    "gitmcp": {
      "url": "https://gitmcp.io/{owner}/{repo}"
    }
  }
}

pgsty/pigsty.quickStart:
curl -fsSL https://repo.pigsty.io/get | bash; cd ~/pigsty;
./configure -g    # generate config and random passwords
./deploy.yml      # deploy everything on current node
